(1,	1,	'funnel_email_campaign',	'New Form Submission (Fluent Forms) (Created at 2025-05-17) (1 - 1)',	NULL,	'new-form-submission-fluent-forms-created-at-2025-05-17-1',	'published',	0,	'Thanks For Reaching Out',	'We will be reaching back out shortly',	'<!-- wp:paragraph -->\n<p>Hi {{contact.first_name}},</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Thank you for contacting C Suite Code. We will review your request and respond within 24 business hours.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>For all immediate or urgent requests, please email anthony@csuitecode.com</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Best regards,</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>C Suite Code</p>\n<!-- /wp:paragraph -->',	2,	0,	0,	'',	'',	'',	'',	'',	'simple',	NULL,	'a:2:{s:15:\"template_config\";a:14:{s:13:\"content_width\";i:700;s:15:\"content_padding\";i:20;s:20:\"headings_font_family\";s:141:\"-apple-system, BlinkMacSystemFont, \'Segoe UI\', Roboto, Helvetica, Arial, sans-serif, \'Apple Color Emoji\', \'Segoe UI Emoji\', \'Segoe UI Symbol\'\";s:10:\"text_color\";s:7:\"#202020\";s:10:\"link_color\";s:0:\"\";s:13:\"body_bg_color\";s:7:\"#FAFAFA\";s:16:\"content_bg_color\";s:7:\"#FFFFFF\";s:17:\"footer_text_color\";s:7:\"#202020\";s:19:\"content_font_family\";s:141:\"-apple-system, BlinkMacSystemFont, \'Segoe UI\', Roboto, Helvetica, Arial, sans-serif, \'Apple Color Emoji\', \'Segoe UI Emoji\', \'Segoe UI Symbol\'\";s:15:\"paragraph_color\";s:0:\"\";s:19:\"paragraph_font_size\";s:0:\"\";s:21:\"paragraph_font_family\";s:0:\"\";s:21:\"paragraph_line_height\";s:0:\"\";s:14:\"headings_color\";s:7:\"#202020\";}s:15:\"mailer_settings\";a:5:{s:9:\"from_name\";s:0:\"\";s:10:\"from_email\";s:0:\"\";s:13:\"reply_to_name\";s:0:\"\";s:14:\"reply_to_email\";s:0:\"\";s:9:\"is_custom\";s:2:\"no\";}}',	1,	'2025-05-18 05:16:23',	'2025-05-18 05:58:27');
